function Assert-AdditiveSql([string]$Path){$sql=Get-Content -Raw -LiteralPath $Path;if($sql.Length-gt16777216){throw 'MIGRATION_SQL_TOO_LARGE'};$withoutComments=[regex]::Replace($sql,'(?ms)/\*.*?\*/|--[^\r\n]*',' ');$forbidden=@('(?i)\bDROP\s+(?:TABLE|COLUMN|SCHEMA|TYPE|INDEX|CONSTRAINT|TRIGGER|FUNCTION|PROCEDURE|VIEW|MATERIALIZED\s+VIEW|SEQUENCE|POLICY|RULE)\b','(?i)\bTRUNCATE\b','(?i)\bALTER\s+TABLE\b[\s\S]*?\bRENAME\b','(?i)\bALTER\s+COLUMN\b[\s\S]*?\b(?:TYPE|SET\s+DATA\s+TYPE|SET\s+NOT\s+NULL|DROP\s+DEFAULT)\b','(?i)\b(?:DELETE\s+FROM|UPDATE\s+[^\s]+\s+SET|INSERT\s+INTO)\b','(?i)\bCREATE\s+(?:OR\s+REPLACE\s+)?FUNCTION\b[\s\S]*?\bSECURITY\s+DEFINER\b','(?i)\bALTER\s+TYPE\b[\s\S]*?\bRENAME\b','(?i)\b(?:DO|CALL|EXECUTE)\b','(?i)\bCREATE\s+(?:EVENT\s+)?TRIGGER\b');foreach($pattern in $forbidden){if($withoutComments-match$pattern){throw 'NON_ADDITIVE_MIGRATION_REJECTED'}}}
